import{_ as t,o as r,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-10-23 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-10-23 :: Ceph Orchestration Meeting","date":"2019-10-23T00:00:00.000Z","updated":"2019-11-01T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","CephFS","Storage Cluster"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-23_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-10-23_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-10-23_-_-_Ceph_Orchestration_Meeting.md"};function s(a,e,n,p,h,_){return r(),i("div",null,[...e[0]||(e[0]=[l("<p>本次会议纪要主要讨论了Ceph分布式存储项目的进展、Orchestrator组件的介绍以及后续工作安排。以下是会议的关键细节和讨论议题：</p><ol><li><p><strong>Drive Group预览功能</strong>：</p><ul><li>Keifa提到需要对Drive Group的预览功能进行审查，以便在合并后可以在仪表板上实现预览功能。</li><li>该功能目前尚未实际使用，因此需要有人进行单元测试和实际应用。</li></ul></li><li><p><strong>Inventory清理</strong>：</p><ul><li>II提到Inventory部分需要清理，但目前仍等待最新成员的审查。</li></ul></li><li><p><strong>Orchestrator组件</strong>：</p><ul><li>Joshua Hesketh刚加入存储团队，正在学习Orchestrator组件。</li><li>Orchestrator组件是一个接口，用于创建、部署、移除服务以及获取运行在集群上的服务列表。</li><li>Orchestrator组件旨在构建Ceph和部署工具（如Rook、DeepSea等）之间的桥梁。</li><li>Orchestrator接口允许不同的orchestrator后端实现该接口，从而在Surf仪表板上实现部署任务。</li></ul></li><li><p><strong>Dashboard支持</strong>：</p><ul><li>如果部署工具没有Orchestrator模块，则无法通过内置的Chef仪表板进行部署。</li><li>Keifer正在为Dashboard添加新功能，例如从GUI部署新的OS Days，这需要通过Orchestrator模块实现。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>Keifa将创建一个PR来读取pison comical，以开始更多choline模块的工作。</li><li>Joshua Hesketh将学习Orchestrator组件的文档，并了解其工作原理。</li><li>II将继续清理Inventory部分。</li></ul></li></ol><p>会议决定事项包括：</p><ul><li>Keifa将审查Drive Group预览功能，并在合并后进行测试。</li><li>Joshua Hesketh将学习Orchestrator组件的文档，并了解其工作原理。</li><li>II将继续清理Inventory部分。</li></ul><p>后续行动计划包括：</p><ul><li>Keifa创建PR并开始更多choline模块的工作。</li><li>Joshua Hesketh学习Orchestrator组件的文档。</li><li>II清理Inventory部分。</li></ul>",6)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
